assert c.sizeof(c.c_void_p)==8
k=c.WinDLL('kernel32',use_last_error=True);k.GetLogicalProcessorInformationEx.argtypes=[c.c_int,c.c_void_p,c.POINTER(c.c_uint32)];k.GetLogicalProcessorInformationEx.restype=c.c_int
n=c.c_uint32();assert not k.GetLogicalProcessorInformationEx(0,None,c.byref(n)) and c.get_last_error()==122 and 0<n.value<65536
buffer=c.create_string_buffer(n.value);assert k.GetLogicalProcessorInformationEx(0,buffer,c.byref(n));raw=buffer.raw[:n.value];(H/'processor-core.bin').write_bytes(raw)
cores=[];at=0;union=chosen=0
while at<len(raw):
 relation,size=struct.unpack_from('<II',raw,at);assert relation==0 and size==48 and at+size<=len(raw)
 flags,eff=struct.unpack_from('<BB',raw,at+8);gc=struct.unpack_from('<H',raw,at+30)[0];mask,group=struct.unpack_from('<QH',raw,at+32)
 assert gc==1 and group==0 and flags==1 and eff==0 and mask.bit_count()==2 and not(union&mask)
 pick=mask&-mask;union|=mask;chosen|=pick;cores.append({'core':len(cores),'group':group,'SMT_flags':flags,'efficiency_class':eff,'mask':mask,'mask_hex':hex(mask),'logical_processors':[x for x in range(64) if mask>>x&1],'chosen_logical_processor':pick.bit_length()-1});at+=size
assert at==len(raw) and len(cores)==16 and union.bit_count()==32 and chosen.bit_count()==16
k.GetCurrentProcess.restype=c.c_void_p;k.GetProcessAffinityMask.argtypes=[c.c_void_p,c.POINTER(c.c_size_t),c.POINTER(c.c_size_t)];k.GetProcessAffinityMask.restype=c.c_int
process,system=c.c_size_t(),c.c_size_t();assert k.GetProcessAffinityMask(k.GetCurrentProcess(),c.byref(process),c.byref(system))
assert process.value==system.value==union
h.save(H/'report.json',{'id':'D200','at':h.now(),'status':'pass_readonly_topology_candidate_fixed','protocol_sha256':h.sha(H/'protocol.json'),'raw_topology_sha256':h.sha(H/'processor-core.bin'),'raw_bytes':len(raw),'cores':cores,'process_allowed_mask':process.value,'system_mask':system.value,'baseline_mask':union,'candidate_mask':chosen,'baseline_mask_hex':hex(union),'candidate_mask_hex':hex(chosen),'workers_both_arms':16,'API_setting_calls':0,'CUDA_or_compiler_or_solver_runs':0,'new_gain_accepted':False,'scope':'ExactcurrentCPUcoreaffinitytopology only. No setting/performance/accuracy/no-tradeoff proof. Maskfixed by physical-core least-significant-bitrule; do not choose siblingbits/CCDsubset/count/priority/OS/clock/source/sample rescue afterfailure.'})
print(json.dumps({'cores':len(cores),'logical_processors':union.bit_count(),'baseline':hex(union),'candidate':hex(chosen),'setting_calls':0}),flush=True)
